const FormatInfo *nvn_format_info(uint32_t f) {
    static const FormatInfo unknown = {SF2C_FORMATS_N_4_4B22, 1, 1, FMT_COLOR, 0};
    if (f >= sizeof formats / sizeof *formats || !formats[f].bpb) return &unknown;
    return &formats[f];
}
